// —— In1：GND 总线 + 焊盘过孔 ——
const gndSpineY = 1280;
const gndPts = [];
for (const [ref, num] of [
  ['U1', 4], ['U2', 4], ['U2', 5], ['U3', 4], ['U3', 5], ['Rg3', 2],
  ['U5', 1], ['CT', 2], ['CD555', 2], ['CC555', 2], ['D555', 2],
  ['REG1', 2], ['REG2', 2], ['REG3', 2],
  ['CI1', 2], ['CI2', 2], ['CI3', 2], ['CO1', 2], ['CO2', 2], ['CO3', 2],
  ['RL1', 2], ['RL2', 2], ['RL3', 2], ['U4', 3], ['CBI', 2], ['CBO', 2], ['RFB', 2]
]) {
  const p = pw(ref, num);
  if (!p || !gnd) continue;
  addVia(gnd, p);
  const tip = { x: p.x, y: p.y + 40 };
  add(gnd, p, tip, 12, 'In1.Cu');
  gndPts.push(tip);
}
if (gnd && gndPts.length) {
  const xs = gndPts.map(p => p.x).sort((a, b) => a - b);
  add(gnd, { x: xs[0] - 20, y: gndSpineY }, { x: xs[xs.length - 1] + 20, y: gndSpineY }, 20, 'In1.Cu');
  for (const p of gndPts) {
    add(gnd, p, { x: p.x, y: gndSpineY }, 12, 'In1.Cu');
  }
}

