  ['RL1', 2], ['RL2', 2], ['RL3', 2], ['U4', 3], ['CBI', 2], ['CBO', 2], ['RFB', 2]
]) {
  const p = pw(ref, num);
  if (!p || !gnd) continue;
  addVia(gnd, p);
  const tip = { x: p.x - 40, y: p.y };
  add(gnd, p, tip, 12, 'In1.Cu');
  gndPts.push(tip);
}
if (gnd && gndPts.length) {
